package ru.neverland.townychronicles.service;
import java.util.*;
import java.nio.file.Path;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.entity.PlayerDeathEvent;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.java.JavaPlugin;
import ru.neverland.core.*;
import ru.neverland.townychronicles.integration.TownyHook;
import ru.neverland.townychronicles.model.*;

public final class ContributionsMenu implements Listener,AutoCloseable {
    private final JavaPlugin plugin;private final TownyHook towns;private final ChronicleRepository repository;private final ThreadPoolExecutor worker;private final AtomicBoolean reading=new AtomicBoolean();
    private volatile Map<UUID,List<CityContributions.Member>> snapshot=Map.of();private volatile String error="История загружается";private volatile long refreshed;
    public ContributionsMenu(JavaPlugin plugin,TownyHook towns,ChronicleRepository repository){this.plugin=plugin;this.towns=towns;this.repository=repository;worker=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(8),r->{Thread t=new Thread(r,"NeverLand-Public-Contributions");t.setDaemon(true);return t;});Bukkit.getPluginManager().registerEvents(this,plugin);SuiteScheduler.get().runTaskTimer(plugin,this::refresh,1,1200);}
    private void refresh(){if(!reading.compareAndSet(false,true))return;var directories=new ArrayList<Path>();for(String name:List.of("NeverLandTownyBuilds","NeverLandTownyContracts","NeverLandTownySiegesPlus","NeverLandTownyControl",plugin.getName())){var p=Bukkit.getPluginManager().getPlugin(name);if(p!=null)directories.add(p.getDataFolder().toPath().resolve("audit"));}try{worker.execute(()->{try{var records=new ArrayList<AuditRecord>();for(Path path:directories)AuditJournal.scan(path,records::add);snapshot=CityContributions.aggregate(records);refreshed=System.currentTimeMillis();error="";var thanks=records.stream().filter(r->r.module().equals(plugin.getName())&&r.kind().equals("CITY_COMMENDATION")&&r.outcome().equals("COMPLETED")).sorted(Comparator.comparingLong(AuditRecord::at).reversed()).limit(1000).toList();SuiteScheduler.get().runTask(plugin,()->{for(var r:thanks)restore(r);repository.requestSave();});}catch(Exception ex){error="Не удалось обновить историю. Последние сведения сохранены";plugin.getLogger().warning("Вклад жителей: "+ex.getMessage());}finally{reading.set(false);}});}catch(RejectedExecutionException ex){reading.set(false);}}
    private void restore(AuditRecord r){UUID town=UUID.fromString(r.from().id()),id=UUID.fromString(r.id());var entries=repository.entries(town);if(entries.stream().anyMatch(e->e.id().equals(id)))return;if(!entries.isEmpty()&&entries.size()>=plugin.getConfig().getInt("storage.maximum-entries-per-town",1000)&&r.at()<entries.get(entries.size()-1).timestamp())return;repository.state(town);repository.add(new ChronicleEntry(id,town,r.from().name(),ChronicleCategory.CUSTOM,r.at(),"Благодарность: "+r.to().name(),List.of(r.details()),r.actor().name(),"mayor-commendation"));}
    public void thank(Player p,String resident,String text){var town=towns.town(p);var r=com.palmergames.bukkit.towny.TownyAPI.getInstance().getResident(resident);if(town==null||!town.isMayor(towns.resident(p))||!p.hasPermission("townychronicles.thank"))throw new IllegalArgumentException("Благодарности публикует мэр города");if(r==null||!town.equals(r.getTownOrNull()))throw new IllegalArgumentException("Этот житель не состоит в вашем городе");String plain=text.strip();if(plain.length()<5||plain.length()>160||plain.chars().anyMatch(c->Character.isISOControl(c)||c=='§'||c=='&'))throw new IllegalArgumentException("Благодарность: 5–160 символов без цветов");long now=System.currentTimeMillis();if(repository.entries(town.getUUID()).stream().anyMatch(e->e.source().equals("mayor-commendation")&&e.timestamp()>now-60_000))throw new IllegalArgumentException("Подождите минуту перед следующей благодарностью");String op=UUID.randomUUID().toString();var actor=AuditTrail.player(p.getUniqueId());var city=AuditTrail.town(town.getUUID());var person=AuditTrail.player(r.getUUID());try{AuditTrail.require(AuditTrail.record(plugin,"thanks",op,"CITY_COMMENDATION","COMPLETED",actor,city,person,"",0,"",plain));}catch(Exception ex){throw new IllegalArgumentException("Благодарность не опубликована: не удалось сохранить запись",ex);}String id=AuditRecord.id(plugin.getName(),op,"thanks");restore(new AuditRecord(id,now,plugin.getName(),"CITY_COMMENDATION","COMPLETED",op,actor,city,person,"",0,"",plain));repository.requestSave();refresh();p.sendMessage("§aБлагодарность сохранена в летописи города");}
    public void open(Player p,int requested){var town=towns.town(p);if(town==null||!p.hasPermission("townychronicles.contributions"))throw new IllegalArgumentException("Раздел вклада доступен жителям города");List<CityContributions.Member> list=snapshot.getOrDefault(town.getUUID(),List.of());int pages=Math.max(1,(list.size()+44)/45),page=Math.max(0,Math.min(requested,pages-1));View v=new View(p.getUniqueId(),town.getUUID(),page);v.inventory=MenuStyle.inventory(plugin,v,54,"Вклад жителей • "+town.getName());for(int i=page*45;i<Math.min(list.size(),(page+1)*45);i++){var m=list.get(i);v.inventory.setItem(i%45,item(Material.PLAYER_HEAD,m.name(),List.of("Материалы из личного инвентаря: "+m.materials()+" шт.","Личные взносы в казну: "+m.deposits().toPlainString(),"Организовано ремонтов: "+m.repairs(),"На ремонт потрачено из казны: "+m.repairBudget().toPlainString(),"Победы над нападавшими: "+m.defense(),"Благодарности мэра: "+m.thanks())));}if(list.isEmpty())v.inventory.setItem(22,item(Material.BOOK,"Записей пока нет",List.of("Здесь появятся взносы, ремонты и защита города")));if(page>0)v.inventory.setItem(45,item(Material.ARROW,"Предыдущая страница",List.of()));if(page+1<pages)v.inventory.setItem(53,item(Material.ARROW,"Следующая страница",List.of()));v.inventory.setItem(49,item(Material.ARROW,"Назад в летопись",List.of("Обновление раз в минуту",error.isEmpty()?"Последнее обновление: "+java.time.Instant.ofEpochMilli(refreshed):error,"Мэр: /t chronicles thank <житель> <текст>")));p.openInventory(v.inventory);}
    @EventHandler public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof View v))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p)||!p.getUniqueId().equals(v.owner)||SuiteState.frozen(plugin.getName()))return;int slot=e.getRawSlot();SuiteScheduler.player(plugin,p,x->{try{var town=towns.town(p);if(town==null||!town.getUUID().equals(v.town)){p.closeInventory();return;}if(slot==49)p.performCommand("chronicles");else if(slot==45)open(p,v.page-1);else if(slot==53)open(p,v.page+1);}catch(Exception ex){p.sendMessage("§e"+ex.getMessage());}});}
    @EventHandler public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof View)e.setCancelled(true);}
    @SuppressWarnings("unchecked") @EventHandler(priority=EventPriority.MONITOR)public void defense(PlayerDeathEvent e){try(var g=SuiteState.guard()){if(SuiteState.frozen(plugin.getName())||!Bukkit.getPluginManager().isPluginEnabled("NeverLandTownySiegesPlus"))return;Player killer=e.getEntity().getKiller();if(killer==null)return;UUID victim=e.getEntity().getUniqueId(),actor=killer.getUniqueId();var own=towns.townOf(actor);var enemy=towns.townOf(victim);var at=com.palmergames.bukkit.towny.TownyAPI.getInstance().getTown(e.getEntity().getLocation());if(own==null||enemy==null||at==null||!at.equals(own))return;var wars=(Collection<Map<String,Object>>)ApiServices.call("NeverLandTownySiegesPlus","ru.neverland.townysieges.api.TownySiegesApi","raids",new Class<?>[]{});for(var war:wars)if(own.getUUID().equals(war.get("defender"))&&enemy.getUUID().equals(war.get("attacker"))&&Boolean.TRUE.equals(war.get("fighting"))){String op=war.get("id")+":"+victim+":"+actor;AuditTrail.record(plugin,"defense",op,"CITY_DEFENSE","COMPLETED",AuditTrail.player(actor),AuditTrail.town(own.getUUID()),AuditTrail.town(enemy.getUUID()),"",1,"","Отражение нападения в своём городе; одна запись на противника за рейд");break;}}catch(Exception ignored){/* Missing war evidence never invents a defense achievement. */}}
    private static ItemStack item(Material type,String name,List<String> lore){var item=new ItemStack(type);var meta=item.getItemMeta();meta.displayName(MenuStyle.nameComponent(MenuStyle.decode(name)));meta.lore(MenuStyle.loreComponents(lore.stream().map(MenuStyle::decode).toList()));meta.addItemFlags(ItemFlag.values());item.setItemMeta(meta);return item;}
    private static final class View implements InventoryHolder{final UUID owner,town;final int page;Inventory inventory;View(UUID owner,UUID town,int page){this.owner=owner;this.town=town;this.page=page;}public Inventory getInventory(){return inventory;}}
    public void close(){worker.shutdown();}
}
